#!/usr/bin/env node
/**
 * Composition root: the only place that creates the concrete adapters from
 * `infra/` and hands them to the commands in `cli/`. It also maps any error a
 * command throws to a message on stderr and a non-zero exit code.
 */
import { Command } from 'commander';
import { readFileSync } from 'node:fs';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';
import { CosmiconfigConfigStore } from '../infra/configStore.js';
import { ExecaProcessRunner } from '../infra/processRunner.js';
import { InquirerPrompter } from '../infra/prompter.js';
import { registerDoctorCommand } from './commands/doctor.js';
import { registerGreetCommand } from './commands/greet.js';

const BIN_NAME = '{{{binName}}}';

const here = dirname(fileURLToPath(import.meta.url));
const { version } = JSON.parse(readFileSync(join(here, '../../package.json'), 'utf8')) as { version: string };

function reportError(error: unknown): void {
  console.error(`Error: ${error instanceof Error ? error.message : String(error)}`);
  // DEBUG=1 adds the stack trace; it is never printed otherwise.
  if (process.env['DEBUG'] === '1' && error instanceof Error && error.stack) {
    console.error(error.stack);
  }
}

const program = new Command();

program.name(BIN_NAME).description('{{{description}}}').version(version);

registerGreetCommand(program, {
  prompter: new InquirerPrompter(),
  configStore: new CosmiconfigConfigStore(BIN_NAME),
  canPrompt: () => Boolean(process.stdin.isTTY),
  cwd: () => process.cwd(),
  stdout: (line) => console.log(line),
});

registerDoctorCommand(program, {
  processRunner: new ExecaProcessRunner(),
  stdout: (line) => console.log(line),
});

try {
  await program.parseAsync();
} catch (error) {
  reportError(error);
  process.exitCode = 1;
}

import { InvalidArgumentError, type Command } from 'commander';
import { parseConfig } from '../../core/config.js';
import type { ConfigStore, Prompter } from '../../core/ports.js';

export interface GreetDependencies {
  prompter: Prompter;
  configStore: ConfigStore;
  /** Whether a person can answer a prompt (an interactive terminal is attached). */
  canPrompt: () => boolean;
  cwd: () => string;
  stdout: (line: string) => void;
}

export interface GreetOptions {
  times?: number;
  shout?: boolean;
}

/** Parses `--times`: a positive integer written in plain digits. */
export function parseTimes(value: string): number {
  const parsed = Number(value);
  if (!/^[1-9][0-9]*$/.test(value) || !Number.isSafeInteger(parsed)) {
    throw new InvalidArgumentError('Must be a positive integer.');
  }
  return parsed;
}

export function registerGreetCommand(program: Command, deps: GreetDependencies): void {
  program
    .command('greet')
    .description('Print a greeting')
    .argument('[name]', 'who to greet (asked interactively when omitted)')
    .option('--times <n>', 'repeat the greeting n times (a positive integer; default 1)', parseTimes)
    .option('--shout', 'print the greeting in upper case')
    .action(async (name: string | undefined, options: GreetOptions) => {
      await runGreet(name, options, deps);
    });
}

/**
 * Settings resolve in this order: a command-line flag, then the configuration
 * file, then the built-in default. The configuration is read first so an
 * invalid file is reported before the user is asked anything.
 */
export async function runGreet(nameArg: string | undefined, options: GreetOptions, deps: GreetDependencies): Promise<void> {
  const loaded = await deps.configStore.load(deps.cwd());
  const config = parseConfig(loaded?.config, loaded?.filepath);

  const name = (nameArg ?? (await askForName(deps))).trim();
  if (name === '') throw new Error('The name must not be empty.');

  const times = options.times ?? config.times;
  const shout = options.shout ?? config.shout;
  const greeting = `${config.greeting}, ${name}!`;
  const line = shout ? greeting.toUpperCase() : greeting;
  for (let i = 0; i < times; i += 1) deps.stdout(line);
}

async function askForName(deps: GreetDependencies): Promise<string> {
  if (!deps.canPrompt()) {
    throw new Error('Missing name: pass it as an argument (there is no interactive terminal to ask for it).');
  }
  return deps.prompter.ask('Who should I greet?');
}

import type { Command } from 'commander';
import type { ProcessRunner } from '../../core/ports.js';

export interface DoctorDependencies {
  processRunner: ProcessRunner;
  stdout: (line: string) => void;
}

export function registerDoctorCommand(program: Command, deps: DoctorDependencies): void {
  program
    .command('doctor')
    .description('Check the environment: print the Node.js version')
    .action(async () => {
      await runDoctor(deps);
    });
}

export async function runDoctor(deps: DoctorDependencies): Promise<void> {
  let version: string;
  try {
    version = await deps.processRunner.run('node', ['--version']);
  } catch (cause) {
    const reason = cause instanceof Error ? cause.message : String(cause);
    throw new Error(`Could not run "node --version": ${reason}`, { cause });
  }
  deps.stdout(`node: ${version.trim()}`);
}

/**
 * Ports: the capabilities the commands need from the outside world, declared
 * as interfaces so `cli/` depends on abstractions and `infra/` provides the
 * concrete adapters (dependency inversion). Nothing in here imports a library.
 */

/** Asks the user for a line of text. */
export interface Prompter {
  ask(message: string): Promise<string>;
}

/** Runs a child process and resolves with its standard output. Rejects when it cannot run or exits non-zero. */
export interface ProcessRunner {
  run(command: string, args: string[]): Promise<string>;
}

/** A configuration file found on disk, before it is validated. */
export interface LoadedConfig {
  filepath: string;
  config: unknown;
}

/** Finds the project configuration, searching upward from a directory. Resolves `undefined` when there is none. */
export interface ConfigStore {
  load(searchFrom: string): Promise<LoadedConfig | undefined>;
}

/**
 * The configuration contract: a zod schema, its defaults and the error raised
 * for an invalid file. Pure: no I/O, so it is tested without touching the disk.
 */
import { z } from 'zod';

export const DEFAULT_GREETING = 'Hello';

/** Unknown keys are rejected so a typo in a config file is reported instead of silently ignored. */
const configSchema = z.strictObject({
  greeting: z.string().trim().min(1).default(DEFAULT_GREETING),
  times: z.number().int().positive().default(1),
  shout: z.boolean().default(false),
});

export type Config = z.infer<typeof configSchema>;

export class ConfigError extends Error {
  constructor(message: string) {
    super(message);
    this.name = 'ConfigError';
  }
}

/**
 * Validates a raw configuration value and fills in the defaults. `raw` is
 * `undefined` when no file was found, which yields the defaults. `source` is
 * the file the value came from and is only used in the error message.
 */
export function parseConfig(raw: unknown, source?: string): Config {
  const result = configSchema.safeParse(raw ?? {});
  if (result.success) return result.data;
  const where = source === undefined ? '' : ` in ${source}`;
  const details = result.error.issues
    .map((issue) => `${issue.path.length > 0 ? issue.path.join('.') : '(root)'}: ${issue.message}`)
    .join('; ');
  throw new ConfigError(`Invalid configuration${where}: ${details}`);
}

/**
 * Interactive-prompt adapter: implements the `Prompter` port over
 * @inquirer/prompts. The only place that knows about a prompting library.
 */
import { input } from '@inquirer/prompts';
import type { Prompter } from '../core/ports.js';

/** Streams the prompt reads from and writes to. Defaults to the process terminal; tests pass their own. */
export interface PromptContext {
  input?: NodeJS.ReadableStream;
  output?: NodeJS.WritableStream;
}

export class InquirerPrompter implements Prompter {
  constructor(private readonly context: PromptContext = {}) {}

  async ask(message: string): Promise<string> {
    return input({ message }, this.context);
  }
}

/**
 * Process-execution adapter: implements the `ProcessRunner` port over execa.
 *
 * Security: the command and its arguments are passed to execa as separate
 * values and never through a shell, so an argument is never parsed as shell
 * syntax. Do not add `shell: true` or build a command line from user input.
 */
import { execa } from 'execa';
import type { ProcessRunner } from '../core/ports.js';

export class ExecaProcessRunner implements ProcessRunner {
  async run(command: string, args: string[]): Promise<string> {
    const { stdout } = await execa(command, args);
    return stdout;
  }
}

/**
 * Configuration adapter: implements the `ConfigStore` port over cosmiconfig.
 *
 * `searchStrategy: 'project'` is set explicitly because it is what makes the
 * search climb: from the starting directory upward until the first directory
 * that contains a `package.json` (inclusive). cosmiconfig 10 changed the
 * default to `'none'`, which would only look in the starting directory.
 * `searchPlaces` lists the file names this tool reads; a `package.json` is
 * deliberately not one of them.
 */
import { cosmiconfig } from 'cosmiconfig';
import type { ConfigStore, LoadedConfig } from '../core/ports.js';

export class CosmiconfigConfigStore implements ConfigStore {
  private readonly explorer;

  constructor(moduleName: string) {
    this.explorer = cosmiconfig(moduleName, {
      searchStrategy: 'project',
      searchPlaces: [`.${moduleName}rc`, `.${moduleName}rc.json`, `${moduleName}.config.json`],
    });
  }

  async load(searchFrom: string): Promise<LoadedConfig | undefined> {
    const result = await this.explorer.search(searchFrom);
    if (result === null || result.isEmpty === true) return undefined;
    return { filepath: result.filepath, config: result.config };
  }
}

import { Command, CommanderError } from 'commander';
import { describe, expect, it } from 'vitest';
import { parseTimes, registerGreetCommand } from '../../src/cli/commands/greet.js';
import { ConfigError } from '../../src/core/config.js';
import type { ConfigStore, LoadedConfig, Prompter } from '../../src/core/ports.js';

// The ports are replaced by in-memory fakes, so these tests cover the command
// logic only. The real adapters run in tests/integration/cli.test.ts.

interface Harness {
  stdout: string[];
  stderr: string[];
  prompts: string[];
  searched: string[];
  run: (args: string[]) => Promise<void>;
}

function harness(options: { config?: LoadedConfig; answer?: string; canPrompt?: boolean } = {}): Harness {
  const stdout: string[] = [];
  const stderr: string[] = [];
  const prompts: string[] = [];
  const searched: string[] = [];

  const prompter: Prompter = {
    ask: async (message) => {
      prompts.push(message);
      return options.answer ?? '';
    },
  };
  const configStore: ConfigStore = {
    load: async (searchFrom) => {
      searched.push(searchFrom);
      return options.config;
    },
  };

  const run = async (args: string[]): Promise<void> => {
    const program = new Command();
    program.exitOverride();
    program.configureOutput({ writeOut: () => {}, writeErr: (text) => stderr.push(text) });
    registerGreetCommand(program, {
      prompter,
      configStore,
      canPrompt: () => options.canPrompt ?? false,
      cwd: () => '/work/dir',
      stdout: (line) => stdout.push(line),
    });
    await program.parseAsync(['greet', ...args], { from: 'user' });
  };

  return { stdout, stderr, prompts, searched, run };
}

const withConfig = (config: unknown): LoadedConfig => ({ filepath: '/work/.{{{binName}}}rc', config });

describe('greet', () => {
  it('greets the given name with the default greeting', async () => {
    const h = harness();
    await h.run(['World']);
    expect(h.stdout).toEqual(['Hello, World!']);
  });

  it('searches for the configuration from the current directory', async () => {
    const h = harness();
    await h.run(['World']);
    expect(h.searched).toEqual(['/work/dir']);
  });

  describe('--times', () => {
    it('repeats the greeting that many times', async () => {
      const h = harness();
      await h.run(['World', '--times', '3']);
      expect(h.stdout).toEqual(['Hello, World!', 'Hello, World!', 'Hello, World!']);
    });

    it.each(['0', '-1', '1.5', 'abc', '', '2x', '1e3', '99999999999999999999'])(
      'rejects %j with a usage error and prints nothing',
      async (value) => {
        const h = harness();
        const failure = await h.run(['World', '--times', value]).then(
          () => undefined,
          (error: unknown) => error,
        );
        expect(failure).toBeInstanceOf(CommanderError);
        expect((failure as CommanderError).code).toBe('commander.invalidArgument');
        expect(h.stderr.join('')).toContain('positive integer');
        expect(h.stdout).toEqual([]);
      },
    );
  });

  describe('parseTimes', () => {
    it('returns the number for plain positive integers', () => {
      expect(parseTimes('1')).toBe(1);
      expect(parseTimes('42')).toBe(42);
    });

    it('throws for anything else', () => {
      for (const value of ['0', '01', '+1', ' 1', '1 ', '-3', '2.0', 'NaN', 'Infinity']) {
        expect(() => parseTimes(value), value).toThrow('positive integer');
      }
    });
  });

  describe('--shout', () => {
    it('prints the greeting in upper case', async () => {
      const h = harness();
      await h.run(['World', '--shout']);
      expect(h.stdout).toEqual(['HELLO, WORLD!']);
    });

    it('does not change the case without the flag', async () => {
      const h = harness();
      await h.run(['World']);
      expect(h.stdout).toEqual(['Hello, World!']);
    });
  });

  describe('configuration', () => {
    it('uses the configured greeting', async () => {
      const h = harness({ config: withConfig({ greeting: 'Howdy' }) });
      await h.run(['World']);
      expect(h.stdout).toEqual(['Howdy, World!']);
    });

    it('uses the configured times and shout when no flag is given', async () => {
      const h = harness({ config: withConfig({ times: 2, shout: true }) });
      await h.run(['World']);
      expect(h.stdout).toEqual(['HELLO, WORLD!', 'HELLO, WORLD!']);
    });

    it('lets --times override the configured times, in both directions', async () => {
      const fewer = harness({ config: withConfig({ times: 5 }) });
      await fewer.run(['World', '--times', '2']);
      expect(fewer.stdout).toHaveLength(2);

      const more = harness({ config: withConfig({ times: 2 }) });
      await more.run(['World', '--times', '4']);
      expect(more.stdout).toHaveLength(4);
    });

    it('lets --shout apply when the configuration says shout is off', async () => {
      const h = harness({ config: withConfig({ shout: false }) });
      await h.run(['World', '--shout']);
      expect(h.stdout).toEqual(['HELLO, WORLD!']);
    });

    it('fails with a clear error naming the file when the configuration is invalid', async () => {
      const h = harness({ config: withConfig({ times: 0 }) });
      const failure = await h.run(['World']).then(
        () => undefined,
        (error: unknown) => error,
      );
      expect(failure).toBeInstanceOf(ConfigError);
      expect((failure as Error).message).toContain('/work/.{{{binName}}}rc');
      expect((failure as Error).message).toContain('times');
      expect(h.stdout).toEqual([]);
    });

    it('reports an invalid configuration before asking for a missing name', async () => {
      const h = harness({ config: withConfig({ shout: 'yes' }), canPrompt: true, answer: 'Ada' });
      await expect(h.run([])).rejects.toBeInstanceOf(ConfigError);
      expect(h.prompts).toEqual([]);
    });
  });

  describe('a missing name', () => {
    it('is asked for when a terminal is available', async () => {
      const h = harness({ canPrompt: true, answer: '  Ada  ' });
      await h.run([]);
      expect(h.prompts).toEqual(['Who should I greet?']);
      expect(h.stdout).toEqual(['Hello, Ada!']);
    });

    it('is an error when no terminal is available, and nothing is asked', async () => {
      const h = harness({ canPrompt: false, answer: 'Ada' });
      await expect(h.run([])).rejects.toThrow('Missing name');
      expect(h.prompts).toEqual([]);
      expect(h.stdout).toEqual([]);
    });

    it('is an error when the answer is blank', async () => {
      const h = harness({ canPrompt: true, answer: '   ' });
      await expect(h.run([])).rejects.toThrow('must not be empty');
      expect(h.stdout).toEqual([]);
    });

    it('is not asked for when the name is given', async () => {
      const h = harness({ canPrompt: true, answer: 'Ada' });
      await h.run(['World']);
      expect(h.prompts).toEqual([]);
    });

    it('rejects a blank name given as an argument', async () => {
      const h = harness({ canPrompt: true, answer: 'Ada' });
      await expect(h.run(['  '])).rejects.toThrow('must not be empty');
      expect(h.prompts).toEqual([]);
    });
  });
});

import { Command } from 'commander';
import { describe, expect, it } from 'vitest';
import { registerDoctorCommand, runDoctor } from '../../src/cli/commands/doctor.js';
import type { ProcessRunner } from '../../src/core/ports.js';

// The process runner is an in-memory fake: these tests cover the command logic.
// The real execa adapter runs in tests/integration/cli.test.ts.

function fakeRunner(result: { stdout: string } | { failure: Error }) {
  const calls: Array<{ command: string; args: string[] }> = [];
  const runner: ProcessRunner = {
    run: async (command, args) => {
      calls.push({ command, args });
      if ('failure' in result) throw result.failure;
      return result.stdout;
    },
  };
  return { runner, calls };
}

describe('doctor', () => {
  it('asks the process runner for "node --version" and prints the trimmed result', async () => {
    const { runner, calls } = fakeRunner({ stdout: 'v22.18.0\n' });
    const stdout: string[] = [];
    await runDoctor({ processRunner: runner, stdout: (line) => stdout.push(line) });
    expect(calls).toEqual([{ command: 'node', args: ['--version'] }]);
    expect(stdout).toEqual(['node: v22.18.0']);
  });

  it('fails with a clear error that keeps the cause when the process cannot run, and prints nothing', async () => {
    const failure = new Error('spawn node ENOENT');
    const { runner } = fakeRunner({ failure });
    const stdout: string[] = [];
    const thrown = await runDoctor({ processRunner: runner, stdout: (line) => stdout.push(line) }).then(
      () => undefined,
      (error: unknown) => error,
    );
    expect(thrown).toBeInstanceOf(Error);
    expect((thrown as Error).message).toBe('Could not run "node --version": spawn node ENOENT');
    expect((thrown as Error).cause).toBe(failure);
    expect(stdout).toEqual([]);
  });

  it('is registered as the "doctor" command', async () => {
    const { runner } = fakeRunner({ stdout: 'v22.18.0' });
    const stdout: string[] = [];
    const program = new Command();
    registerDoctorCommand(program, { processRunner: runner, stdout: (line) => stdout.push(line) });
    await program.parseAsync(['doctor'], { from: 'user' });
    expect(stdout).toEqual(['node: v22.18.0']);
  });
});

import { describe, expect, it } from 'vitest';
import { ConfigError, DEFAULT_GREETING, parseConfig } from '../../src/core/config.js';

describe('parseConfig', () => {
  it('returns the defaults when there is no configuration', () => {
    expect(parseConfig(undefined)).toEqual({ greeting: DEFAULT_GREETING, times: 1, shout: false });
    expect(DEFAULT_GREETING).toBe('Hello');
  });

  it('fills in the defaults for the keys that are missing', () => {
    expect(parseConfig({ times: 3 })).toEqual({ greeting: 'Hello', times: 3, shout: false });
  });

  it('keeps every value it is given', () => {
    expect(parseConfig({ greeting: 'Howdy', times: 2, shout: true })).toEqual({ greeting: 'Howdy', times: 2, shout: true });
  });

  it.each([
    ['an unknown key', { colour: 'red' }, 'colour'],
    ['a non-string greeting', { greeting: 5 }, 'greeting'],
    ['a blank greeting', { greeting: '   ' }, 'greeting'],
    ['zero times', { times: 0 }, 'times'],
    ['negative times', { times: -2 }, 'times'],
    ['fractional times', { times: 1.5 }, 'times'],
    ['times as text', { times: '2' }, 'times'],
    ['a non-boolean shout', { shout: 'yes' }, 'shout'],
    ['a non-object value', 'greeting', '(root)'],
    ['an array', [], '(root)'],
  ])('rejects %s with a ConfigError that names the offending key', (_label, raw, key) => {
    expect(() => parseConfig(raw)).toThrow(ConfigError);
    expect(() => parseConfig(raw)).toThrow(key);
  });

  it('names the file in the error when the source is known', () => {
    expect(() => parseConfig({ times: 0 }, '/work/project/.{{{binName}}}rc')).toThrow(
      'Invalid configuration in /work/project/.{{{binName}}}rc: times:',
    );
  });

  it('omits the file from the error when the source is unknown', () => {
    expect(() => parseConfig({ times: 0 })).toThrow(/^Invalid configuration: times:/);
  });

  it('reports every problem at once', () => {
    expect(() => parseConfig({ times: 0, shout: 'yes' })).toThrow(/times:.*shout:/);
  });

  it('names the error class', () => {
    expect(new ConfigError('x').name).toBe('ConfigError');
  });
});

import { readdirSync, readFileSync } from 'node:fs';
import { join } from 'node:path';
import { describe, expect, it } from 'vitest';

// Guards the layering the README describes: cli/ -> core/ <- infra/.
// core/ is the innermost layer and must not know about the others or about libraries.

const SRC = join(import.meta.dirname, '../../src');

/** Every way a module can name a dependency: `from '...'`, a bare `import '...'`, `import('...')` and `require('...')`. */
const IMPORT_SPECIFIERS = [
  /\bfrom\s+'([^']+)'/g,
  /\bimport\s+'([^']+)'/g,
  /\bimport\(\s*'([^']+)'\s*\)/g,
  /\brequire\(\s*'([^']+)'\s*\)/g,
];

function importsOf(layer: string): Array<{ file: string; specifier: string }> {
  const dir = join(SRC, layer);
  return readdirSync(dir, { recursive: true, withFileTypes: true })
    .filter((entry) => entry.isFile() && entry.name.endsWith('.ts'))
    .flatMap((entry) => {
      const path = join(entry.parentPath, entry.name);
      const source = readFileSync(path, 'utf8');
      const file = path.slice(SRC.length + 1).split('\\').join('/');
      return IMPORT_SPECIFIERS.flatMap((pattern) =>
        [...source.matchAll(pattern)].map((match) => ({ file, specifier: match[1] as string })),
      );
    });
}

describe('layering', () => {
  it('finds the imports it is supposed to check', () => {
    expect(importsOf('core').length).toBeGreaterThan(0);
    expect(importsOf('cli').length).toBeGreaterThan(0);
    expect(importsOf('infra').length).toBeGreaterThan(0);
  });

  it('keeps core/ free of cli/, infra/ and every package except zod', () => {
    for (const { file, specifier } of importsOf('core')) {
      const isSiblingInCore = /^\.\/[A-Za-z]+\.js$/.test(specifier);
      expect(isSiblingInCore || specifier === 'zod', `${file} imports ${specifier}`).toBe(true);
    }
  });

  it('keeps infra/ from importing cli/', () => {
    for (const { file, specifier } of importsOf('infra')) {
      expect(specifier.includes('/cli/'), `${file} imports ${specifier}`).toBe(false);
    }
  });

  it('lets only the composition root import infra/', () => {
    for (const { file, specifier } of importsOf('cli')) {
      if (file === 'cli/index.ts') continue;
      expect(specifier.includes('/infra/'), `${file} imports ${specifier}`).toBe(false);
    }
  });
});

import { execa } from 'execa';
import { mkdirSync, mkdtempSync, realpathSync, writeFileSync } from 'node:fs';
import { rm } from 'node:fs/promises';
import { tmpdir } from 'node:os';
import { join } from 'node:path';
import { PassThrough } from 'node:stream';
import { afterAll, beforeAll, describe, expect, it } from 'vitest';
import { InquirerPrompter } from '../../src/infra/prompter.js';

// These tests run the compiled binary with the real adapters (execa, cosmiconfig)
// and no fakes. They compile the project first so `npm test` works on a fresh clone.

const ROOT = join(import.meta.dirname, '../..');
const BIN = join(ROOT, 'dist/cli/index.js');
const TSC = join(ROOT, 'node_modules/typescript/bin/tsc');
const RC_FILE = '.{{{binName}}}rc';

/** Temporary directory trees; each test builds its own, with an explicit package.json as the search boundary. */
const roots: string[] = [];

function makeRoot(): string {
  const root = realpathSync.native(mkdtempSync(join(tmpdir(), 'cli-test-')));
  roots.push(root);
  return root;
}

function write(path: string, content: string): void {
  mkdirSync(join(path, '..'), { recursive: true });
  writeFileSync(path, content);
}

/** A project directory (it has a package.json, which stops the configuration search) with an optional config file. */
function makeProject(config?: string): string {
  const root = makeRoot();
  write(join(root, 'package.json'), '{}');
  if (config !== undefined) write(join(root, RC_FILE), config);
  return root;
}

interface Result {
  exitCode: number;
  stdout: string;
  stderr: string;
}

async function runCli(args: string[], options: { cwd: string; debug?: boolean; env?: Record<string, string> }): Promise<Result> {
  const { exitCode, stdout, stderr } = await execa(process.execPath, [BIN, ...args], {
    cwd: options.cwd,
    reject: false,
    env: { DEBUG: options.debug ? '1' : '', ...options.env },
  });
  return { exitCode: exitCode ?? -1, stdout, stderr };
}

beforeAll(async () => {
  await execa(process.execPath, [TSC, '-p', 'tsconfig.json'], { cwd: ROOT });
});

afterAll(async () => {
  for (const root of roots) {
    await rm(root, { recursive: true, force: true, maxRetries: 10, retryDelay: 100 });
  }
});

describe('greet (built binary)', () => {
  it('prints the greeting', async () => {
    const result = await runCli(['greet', 'World'], { cwd: makeProject() });
    expect(result).toMatchObject({ exitCode: 0, stdout: 'Hello, World!', stderr: '' });
  });

  it('honours --times and --shout', async () => {
    const result = await runCli(['greet', 'World', '--times', '2', '--shout'], { cwd: makeProject() });
    expect(result.exitCode).toBe(0);
    expect(result.stdout).toBe('HELLO, WORLD!\nHELLO, WORLD!');
  });

  it('rejects an invalid --times on stderr with a non-zero exit code', async () => {
    const result = await runCli(['greet', 'World', '--times', '0'], { cwd: makeProject() });
    expect(result.exitCode).toBe(1);
    expect(result.stdout).toBe('');
    expect(result.stderr).toContain('positive integer');
  });

  it('asks for the name only on a terminal: with none attached it fails on stderr', async () => {
    const result = await runCli(['greet'], { cwd: makeProject() });
    expect(result.exitCode).toBe(1);
    expect(result.stdout).toBe('');
    expect(result.stderr).toContain('Missing name');
  });

  it('reports --version and --help', async () => {
    const cwd = makeProject();
    expect((await runCli(['--version'], { cwd })).stdout).toMatch(/^\d+\.\d+\.\d+/);
    const help = await runCli(['--help'], { cwd });
    expect(help.stdout).toContain('greet');
    expect(help.stdout).toContain('doctor');
  });
});

describe('configuration (real cosmiconfig)', () => {
  it('is read from the current directory', async () => {
    const result = await runCli(['greet', 'World'], { cwd: makeProject('{ "greeting": "Hi" }') });
    expect(result.stdout).toBe('Hi, World!');
  });

  it('is found by searching upward from a subdirectory', async () => {
    const project = makeProject('{ "greeting": "Hi" }');
    const nested = join(project, 'a', 'b');
    mkdirSync(nested, { recursive: true });
    const result = await runCli(['greet', 'World'], { cwd: nested });
    expect(result.stdout).toBe('Hi, World!');
  });

  it('is also read from {{{binName}}}.config.json', async () => {
    const project = makeProject();
    write(join(project, '{{{binName}}}.config.json'), '{ "greeting": "Yo" }');
    const result = await runCli(['greet', 'World'], { cwd: project });
    expect(result.stdout).toBe('Yo, World!');
  });

  it('stops searching at the first directory that has a package.json', async () => {
    const outer = makeRoot();
    write(join(outer, RC_FILE), '{ "greeting": "Outer" }');
    const inner = join(outer, 'inner');
    write(join(inner, 'package.json'), '{}');
    const result = await runCli(['greet', 'World'], { cwd: inner });
    expect(result.stdout).toBe('Hello, World!');
  });

  it('is overridden by command-line flags', async () => {
    const project = makeProject('{ "times": 3 }');
    expect((await runCli(['greet', 'World'], { cwd: project })).stdout.split('\n')).toHaveLength(3);
    expect((await runCli(['greet', 'World', '--times', '2'], { cwd: project })).stdout.split('\n')).toHaveLength(2);
  });

  it('fails with a clear error when a value is invalid', async () => {
    const result = await runCli(['greet', 'World'], { cwd: makeProject('{ "times": 0 }') });
    expect(result.exitCode).toBe(1);
    expect(result.stdout).toBe('');
    expect(result.stderr).toContain('Invalid configuration');
    expect(result.stderr).toContain(RC_FILE);
    expect(result.stderr).toContain('times');
  });

  it('fails with a clear error when the file cannot be parsed', async () => {
    const result = await runCli(['greet', 'World'], { cwd: makeProject('{ not valid') });
    expect(result.exitCode).toBe(1);
    expect(result.stderr).toContain(RC_FILE);
  });
});

describe('error output (DEBUG)', () => {
  const failing = () => makeProject('{ "times": 0 }');

  it('prints only the message by default', async () => {
    const result = await runCli(['greet', 'World'], { cwd: failing() });
    expect(result.exitCode).toBe(1);
    expect(result.stderr).toMatch(/^Error: Invalid configuration/);
    expect(result.stderr).not.toMatch(/\n\s+at /);
  });

  it('adds the stack trace with DEBUG=1', async () => {
    const result = await runCli(['greet', 'World'], { cwd: failing(), debug: true });
    expect(result.exitCode).toBe(1);
    expect(result.stderr).toMatch(/^Error: Invalid configuration/);
    expect(result.stderr).toMatch(/\n\s+at /);
  });
});

describe('doctor (real execa)', () => {
  it('prints the Node.js version reported by the real process', async () => {
    const result = await runCli(['doctor'], { cwd: makeProject() });
    expect(result.exitCode).toBe(0);
    expect(result.stdout).toMatch(/^node: v\d+\.\d+\.\d+/);
  });

  // Windows resolves executables through more than PATH, so an empty PATH is not a reliable way to make `node` unavailable there.
  it.skipIf(process.platform === 'win32')('fails on stderr with a non-zero exit code when `node` cannot be run', async () => {
    const emptyDir = makeRoot();
    const result = await execa(process.execPath, [BIN, 'doctor'], {
      cwd: emptyDir,
      reject: false,
      extendEnv: false,
      env: { PATH: emptyDir },
    });
    expect(result.exitCode).toBe(1);
    expect(result.stdout).toBe('');
    expect(result.stderr).toContain('Could not run "node --version"');
  });
});

describe('InquirerPrompter (real @inquirer/prompts, scripted input stream)', () => {
  it('returns what the user types', async () => {
    const input = new PassThrough();
    const output = new PassThrough();
    const prompter = new InquirerPrompter({ input, output });
    const answer = prompter.ask('Who should I greet?');
    input.write('Ada\n');
    await expect(answer).resolves.toBe('Ada');
  });
});
